mapper.select:
select * from fitian.Channel
where boxCode = #{boxCode}
and channelId = #{channelId}

select c.channelId, c.channelName, c.type from fitian.Channel c 
inner join fitian.Channel_participant cp  on c.channelId = cp.channelId 
where c.boxCode = #{boxCode} and cp.uid = #{uid}

mapper.delete:
delete from fitian.Channel
where boxCode = #{boxCode}
and channelId = #{channelId}
